cd /tmp/gne-runs/05-AC-r5-1791702374/work/src/main/java/com/fream/back/domain; python3 - <<'E'
p='user/repository/PointRepository.java'
s=open(p).read()
s=s.replace("    // 사용자의 모든 포인트 내역 조회","    boolean existsByUserAndReason(User user, String reason);\n\n    // 사용자의 모든 포인트 내역 조회",1)
open(p,'w').write(s)

p='user/service/point/PointCommandService.java'
s=open(p).read()
s=s.replace('''    /**
     * 포인트 사용
     */''','''    /**
     * 구매 적립 (주문 총액의 1%, 1포인트 미만 버림, 주문당 1회)
     *
     * @return 적립된 포인트 (적립하지 않으면 0)
     */
    @Transactional
    public int rewardPurchase(User user, Long orderId, int totalAmount) {
        int reward = (int) (Math.max(totalAmount, 0) / 100L);
        if (reward <= 0) {
            return 0;
        }
        String reason = "구매 적립 (주문 ID: " + orderId + ")";
        if (pointRepository.existsByUserAndReason(user, reason)) {
            log.info("이미 구매 적립된 주문: orderId={}", orderId);
            return 0;
        }
        pointRepository.save(Point.builder()
                .user(user)
                .amount(reward)
                .remainingAmount(reward)
                .reason(reason)
                .expirationDate(LocalDate.now().plusDays(90))
                .status(PointStatus.AVAILABLE)
                .build());
        return reward;
    }

    /**
     * 포인트 사용
     */''',1)
open(p,'w').write(s)

p='shipment/service/command/OrderShipmentCommandService.java'
s=open(p).read()
s=s.replace("import com.fream.back.domain.user.entity.User;","import com.fream.back.domain.user.entity.User;\nimport com.fream.back.domain.user.service.point.PointCommandService;",1)
s=s.replace("    private final CjTrackingPlaywright cjTrackingPlaywright;\n","    private final CjTrackingPlaywright cjTrackingPlaywright;\n    private final PointCommandService pointCommandService;\n",1)
s=s.replace('''            log.info("구매자 알림 생성 완료: userId={}, orderId={}", buyer.getId(), order.getId());
''','''            log.info("구매자 알림 생성 완료: userId={}, orderId={}", buyer.getId(), order.getId());

            rewardBuyer(order);
''',1)
s=s.replace('''                    log.info("배송 완료 알림 전송: userId={}, orderId={}",
                            buyer.getId(), order.getId());
''','''                    log.info("배송 완료 알림 전송: userId={}, orderId={}",
                            buyer.getId(), order.getId());

                    rewardBuyer(order);
''',1)
s=s.replace('''    /**
     * 주문을 완료 상태로 변경하고''','''    /**
     * 배송 완료된 주문에 대해 구매자에게 구매 적립 포인트를 지급하고 혜택 알림을 보냅니다.
     */
    private void rewardBuyer(Order order) {
        User buyer = order.getUser();
        int reward = pointCommandService.rewardPurchase(buyer, order.getId(), order.getTotalAmount());
        if (reward > 0) {
            notificationCommandService.createNotification(
                    buyer.getId(),
                    NotificationCategory.SHOPPING,
                    NotificationType.BENEFIT,
                    "구매 적립 혜택으로 " + reward + "P가 적립되었습니다. 주문 ID: " + order.getId()
            );
        }
    }

    /**
     * 주문을 완료 상태로 변경하고''',1)
open(p,'w').write(s)
E
